'use strict';

// MODULES //

var tape = require( 'tape' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var real = require( '@stdlib/complex/float64/real' );
var imag = require( '@stdlib/complex/float64/imag' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var untilEach = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof untilEach, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function invokes a callback for the element in a 0-dimensional ndarray when the predicate returns a falsy value', function test( t ) {
	var expected;
	var values;
	var x;

	x = scalar2ndarray( 4.0, {
		'dtype': 'float64'
	});

	values = [];
	untilEach( [ x ], predicate, fcn );

	expected = [ 4.0 ];
	t.deepEqual( values, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return v < 0.0;
	}

	function fcn( v ) {
		values.push( v );
	}
});

tape( 'the function does not invoke a callback for the element in a 0-dimensional ndarray when the predicate returns a truthy value', function test( t ) {
	var expected;
	var values;
	var x;

	x = scalar2ndarray( 4.0, {
		'dtype': 'float64'
	});

	values = [];
	untilEach( [ x ], predicate, fcn );

	expected = [];
	t.deepEqual( values, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return v % 2.0 === 0.0;
	}

	function fcn( v ) {
		values.push( v );
	}
});

tape( 'the function invokes a callback for the element in a 0-dimensional ndarray when the predicate returns a falsy value (accessors)', function test( t ) {
	var expected;
	var values;
	var x;

	x = scalar2ndarray( new Complex128( 3.0, 1.0 ), {
		'dtype': 'complex128'
	});

	values = [];
	untilEach( [ x ], predicate, fcn );

	expected = [
		[ 3.0, 1.0 ]
	];
	t.deepEqual( values, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return real( v ) < 0.0;
	}

	function fcn( v ) {
		values.push( [ real( v ), imag( v ) ] );
	}
});

tape( 'the function does not invoke a callback for the element in a 0-dimensional ndarray when the predicate returns a truthy value (accessors)', function test( t ) {
	var expected;
	var values;
	var x;

	x = scalar2ndarray( new Complex128( 4.0, 1.0 ), {
		'dtype': 'complex128'
	});

	values = [];
	untilEach( [ x ], predicate, fcn );

	expected = [];
	t.deepEqual( values, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return real( v ) % 2.0 === 0.0;
	}

	function fcn( v ) {
		values.push( [ real( v ), imag( v ) ] );
	}
});

tape( 'the function supports specifying the callback execution context', function test( t ) {
	var expected;
	var indices;
	var values;
	var arrays;
	var ctx;
	var x;

	x = scalar2ndarray( 3.0, {
		'dtype': 'float64'
	});

	indices = [];
	values = [];
	arrays = [];

	ctx = {};
	untilEach( [ x ], predicate, fcn, ctx );

	expected = [ 3.0 ];
	t.deepEqual( values, expected, 'returns expected value' );

	expected = [ [] ];
	t.deepEqual( indices, expected, 'returns expected value' );

	expected = [ x ];
	t.deepEqual( arrays, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return v < 0.0;
	}

	function fcn( v, idx, arr ) {
		t.strictEqual( this, ctx, 'returns expected context' ); // eslint-disable-line no-invalid-this
		values.push( v );
		indices.push( idx );
		arrays.push( arr );
	}
});

tape( 'the function supports specifying the callback execution context (accessors)', function test( t ) {
	var expected;
	var indices;
	var values;
	var arrays;
	var ctx;
	var x;

	x = scalar2ndarray( new Complex128( 3.0, 1.0 ), {
		'dtype': 'complex128'
	});

	indices = [];
	values = [];
	arrays = [];

	ctx = {};
	untilEach( [ x ], predicate, fcn, ctx );

	expected = [
		[ 3.0, 1.0 ]
	];
	t.deepEqual( values, expected, 'returns expected value' );

	expected = [ [] ];
	t.deepEqual( indices, expected, 'returns expected value' );

	expected = [ x ];
	t.deepEqual( arrays, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return real( v ) < 0.0;
	}

	function fcn( v, idx, arr ) {
		t.strictEqual( this, ctx, 'returns expected context' ); // eslint-disable-line no-invalid-this
		values.push( [ real( v ), imag( v ) ] );
		indices.push( idx );
		arrays.push( arr );
	}
});
